'use strict';
// Character decisions use only their own hand and publicly visible information.
function aiVisible(i){const c=MJ.counts(G.players[i].hand);for(const p of G.players){for(const r of p.river)if(!r.taken)c[MJ.base(r.t)]++;for(const m of p.melds)for(const t of m.tiles)c[MJ.base(t)]++}for(const t of G.doras)c[MJ.base(t)]++;return c}
function aiRisk(i,t){t=MJ.base(t);let risk=0;const seen=aiVisible(i);for(let j=0;j<4;j++){if(j===i||G.teamMode&&j%2===i%2)continue;const q=G.players[j];if(q.river.some(r=>MJ.base(r.t)===t))continue;const threat=q.riichi?1:q.melds.filter(m=>m.open).length>=2?.55:q.river.length>=10?.25:0;if(!threat)continue;let danger=t>=27?Math.max(0,3-seen[t])/3:1;if(t<27){if(q.river.some(r=>Math.floor(MJ.base(r.t)/9)===Math.floor(t/9)&&Math.abs(MJ.base(r.t)-t)===3))danger*=.6;if(t%9===0||t%9===8)danger*=.75}risk+=threat*danger}return risk}
function aiValue(i,hand,melds){const all=[...hand,...melds.flatMap(m=>m.tiles)],c=MJ.counts(hand),suits=[0,0,0];for(const t of all)if(MJ.base(t)<27)suits[Math.floor(MJ.base(t)/9)]++;const suit=suits.indexOf(Math.max(...suits));const flush=all.filter(t=>MJ.base(t)>=27||Math.floor(MJ.base(t)/9)===suit).length;const compatible=melds.every(m=>m.tiles.every(t=>MJ.base(t)>=27||Math.floor(MJ.base(t)/9)===suit));return {flush:compatible&&flush>=all.length*.65?flush:0,trip:melds.every(m=>m.type!=='chi')?c.reduce((a,n)=>a+(n>=3?5:n===2?2:0),0)+melds.length*5:0,dora:all.filter(t=>MJ.isRed(t)).length+all.reduce((n,t)=>n+G.doras.filter(d=>MJ.nextDora(d)===MJ.base(t)).length,0)}}
function aiSuuankou(i){const p=G.players[i];return castId(i)===3&&!!p.aiCirceAwakened&&!p.melds.some(m=>m.open)}
function aiDiscardChoice(i){const p=G.players[i];if(p.riichi)return p.hand.length-1;const id=castId(i),visible=id===4?MJ.counts(p.hand):aiVisible(i),fallback=MJ.aiDiscard(p.hand,visible,id,p.melds,G.forbidden||[]);const opts=p.hand.map((t,k)=>{const hand=p.hand.filter((_,j)=>j!==k);return {t,k,hand,sh:MJ.shanten(hand,p.melds.length)}}).filter(o=>!(G.forbidden||[]).includes(MJ.base(o.t)));const min=Math.min(...opts.map(o=>o.sh));for(const o of opts){const v=aiValue(i,o.hand,p.melds);o.cost=o.sh*100+(o.k===fallback?-3:0)+(MJ.isRed(o.t)?7:0);if(id===1)o.cost+=aiRisk(i,o.t)*240;if(id===5)o.cost+=aiRisk(i,o.t)*65;if(id===3)o.cost-=v.flush*7+v.trip*(aiSuuankou(i)?28:9)+v.dora*8;if(o.sh===0)o.cost-=MJ.waits(o.hand,p.melds).reduce((n,t)=>n+Math.max(0,4-visible[t]),0)*3}const allowed=opts.filter(o=>o.sh<=min+(id===1?2:id===3?1:0));allowed.sort((a,b)=>a.cost-b.cost||a.k-b.k);const choice=allowed[0]?.k??fallback;return id===1||id===2||id===4?choice:teamDiscard(i,choice)}
function aiDama(i,hand,melds){return MJ.waits(hand,melds).some(t=>MJ.score([...hand,t],{...context(i,false,t),melds,riichi:false,doubleRiichi:false,ippatsu:false,last:false,chankan:false,rinshan:false,firstDraw:false}))}
function aiRiichi(i,rest){if(castId(i)!==1)return true;const p=G.players[i];return !aiDama(i,rest,p.melds)||(G.abilitiesEnabled&&(MJ.counts(rest).some(n=>n===4)||p.melds.some(m=>m.type==='kan')))}
function aiKanAllowed(i,o){const p=G.players[i];if(castId(i)!==1||!G.abilitiesEnabled)return true;const hand=p.hand.slice(),melds=p.melds.map(m=>({...m,tiles:m.tiles.slice()}));if(o.kind==='ankan'){for(let k=hand.length-1;k>=0;k--)if(MJ.base(hand[k])===MJ.base(o.t))hand.splice(k,1);melds.push({type:'kan',tiles:o.tiles,open:false})}else{hand.splice(hand.indexOf(o.t),1);melds[o.index].type='kan';melds[o.index].tiles.push(o.t)}return MJ.waits(hand,melds).length>0}
cpu=function(){const i=G.turn,p=G.players[i];const r=G.afterCall?null:evaluate(i,true,p.hand.at(-1));if(r){finishWin(i,i,p.hand.at(-1),r);return}if(!teamAvoidCall(i)){const kan=kanOptions(i).find(o=>aiKanAllowed(i,o));if(kan){declareKan(kan);return}}const idx=aiDiscardChoice(i),rest=p.hand.filter((_,k)=>k!==idx);if(!teamAvoidCall(i)&&!p.riichi&&!p.melds.some(m=>m.open)&&p.score>=1000&&G.deck.length>=4&&MJ.waits(rest,p.melds).length&&aiRiichi(i,rest)){p.riichi=true;p.ippatsu=true;p.score-=1000;G.pot++;discard(idx,true)}else discard(idx)};
aiCall=function(i,from,t){if(castId(i)===4||teamAvoidCall(i)||aiSuuankou(i))return null;const p=G.players[i],id=castId(i),before=MJ.shanten(p.hand,p.melds.length);let best=null;for(const o of callOptions(i,from,t)){const hand=p.hand.slice();for(const v of o.take)hand.splice(hand.indexOf(v),1);const melds=[...p.melds,{type:o.kind==='minkan'?'kan':o.kind,tiles:o.tiles,open:true}];const options=o.kind==='minkan'?[hand]:hand.map((v,k)=>o.forbidden.includes(MJ.base(v))?null:hand.filter((_,j)=>j!==k)).filter(Boolean);for(const rest of options){const sh=MJ.shanten(rest,melds.length),all=[...rest,...melds.flatMap(m=>m.tiles)],v=aiValue(i,rest,melds);const yakuhai=melds.some(m=>m.type!=='chi'&&m.tiles.some(t=>MJ.base(t)>=31||MJ.base(t)===27+wind(i)||MJ.base(t)===27+roundWind()))||MJ.counts(rest).some((n,t)=>n>=3&&(t>=31||t===27+wind(i)||t===27+roundWind()));const tanyao=all.every(t=>!MJ.terminal(t));const flush=v.flush===all.length;const trip=melds.every(m=>m.type!=='chi')&&MJ.counts(rest).filter(n=>n>=2).length>=4-melds.length;const yaku=yakuhai||tanyao||flush||trip||(sh===0&&aiDama(i,rest,melds));if(!yaku)continue;if(id===1&&o.kind==='minkan'&&G.abilitiesEnabled&&!MJ.waits(rest,melds).length)continue;if(id===1&&aiRisk(i,t)>0.5&&sh>0)continue;if(id===3&&!flush&&!trip&&v.dora<2)continue;if(sh>before||id!==2&&sh===before&&o.kind!=='minkan')continue;const cost=sh*100-(id===3?v.flush*3+v.trip*4+v.dora*8:0);if(!best||cost<best.cost)best={...o,cost}}}return best};


